import{_ as o,o as a,c,ai as i}from"./chunks/framework.Ba-VnP44.js";const h=JSON.parse('{"title":"办公自动化 OA · OpenBiz 第七个独立消费者","description":"","frontmatter":{},"headers":[],"relativePath":"apps/openbiz/oa.md","filePath":"apps/openbiz/oa.md"}'),d={name:"apps/openbiz/oa.md"};function n(p,e,r,t,l,s){return a(),c("div",null,[...e[0]||(e[0]=[i('<h1 id="办公自动化-oa-·-openbiz-第七个独立消费者" tabindex="-1">办公自动化 OA · OpenBiz 第七个独立消费者 <a class="header-anchor" href="#办公自动化-oa-·-openbiz-第七个独立消费者" aria-label="Permalink to “办公自动化 OA · OpenBiz 第七个独立消费者”">​</a></h1><blockquote><p>现为独立应用 <code>openbiz-oa-app</code>（<code>E:/8.cangku/for-job/openbiz-oa-app</code>）：独立后端（端口 18087）+ 独立前端（Vue3/TS）+ 独立数据库 <code>openbiz_oa</code>。</p></blockquote><blockquote><p>实证：OpenBiz 母仓无 OA 域，按 OpenBiz 命名约定自建 <code>openbiz_oa_*</code> 表，在其多租户基座之上实现「请假单 + 公告双状态机」最小闭环。验证 OpenBiz V0.2「更多独立 consumer」目标。</p></blockquote><h2 id="复用与自建" tabindex="-1">复用与自建 <a class="header-anchor" href="#复用与自建" aria-label="Permalink to “复用与自建”">​</a></h2><ul><li><strong>复用</strong>：OpenBiz <code>openbiz-saas-core</code> 多租户（TenantContext / TenantService / 自动装配）、RuoYi 登录外壳</li><li><strong>自建</strong>：<code>openbiz_oa_leave</code> / <code>openbiz_oa_notice</code> 表 + Mapper / Service / Controller <ul><li>请假单状态机：<code>DRAFT → SUBMITTED → APPROVED / REJECTED</code>，活动态 <code>→ WITHDRAWN</code>（仅 SUBMITTED 可转）</li><li>公告状态机：<code>DRAFT → PUBLISHED → ARCHIVED</code>，<code>PUBLISHED ⇄ DRAFT</code>（撤回）</li></ul></li></ul><h2 id="业务闭环-e2e-已验证" tabindex="-1">业务闭环（E2E 已验证） <a class="header-anchor" href="#业务闭环-e2e-已验证" aria-label="Permalink to “业务闭环（E2E 已验证）”">​</a></h2><p>创建请假单(<code>DRAFT</code>) → 提交(<code>SUBMITTED</code>) → 批准(<code>APPROVED</code>)；终态后再提交 / 撤回均被 <code>ILLEGAL_TRANSITION</code> 拒绝。独立路径创建公告(<code>DRAFT</code>) → 发布(<code>PUBLISHED</code>) → 撤回(<code>DRAFT</code>) → 归档(<code>ARCHIVED</code>)；归档后撤回被拒。统计接口 <code>GET /api/oa/{leaves|notices}/stats</code> 返回各状态数量，断言落库一致。</p><h2 id="工程位置" tabindex="-1">工程位置 <a class="header-anchor" href="#工程位置" aria-label="Permalink to “工程位置”">​</a></h2><p><code>E:/8.cangku/for-job/openbiz-oa-app</code>（含 README 与 E2E 脚本，端口 18087）</p><h2 id="价值" tabindex="-1">价值 <a class="header-anchor" href="#价值" aria-label="Permalink to “价值”">​</a></h2><p>与 BPM 同一模块，本例聚焦「面向办公场景的应用组装」（请假 + 公告）。后续 OA 的待办聚合、审批中心可在此之上叠加，复用本状态机骨架。</p><hr><p>上一级：<a href="/my-vitepress-site/apps/openbiz/">OpenBiz 试水实证</a></p>',13)])])}const _=o(d,[["render",n]]);export{h as __pageData,_ as default};
